import{_ as p,a0 as l,w as n,s as u,ao as a,I as e,x as o,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 用户的 7 個 Sudo 技巧和改進 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 用户的 7 個 Sudo 技巧和改進 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 用户的 7 個 Sudo 技巧和改進 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 用户的 7 個 Sudo 技巧和改進 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20231205 7 Sudo Tips and Tweaks for Linux Users","title":"Linux 用户的 7 個 Sudo 技巧和改進","tag":"202312","desc":""},"relativePath":"202312/20231205 7 Sudo Tips and Tweaks for Linux Users.md","filePath":"[post].md"}'),r={name:"202312/20231205 7 Sudo Tips and Tweaks for Linux Users.md"};function g(c,s,h,k,b,f){const d=l("Link");return n(),u("div",null,[s[44]||(s[44]=a('<h1 id="linux-用户的-7-個-sudo-技巧和改進" tabindex="-1">Linux 用户的 7 個 Sudo 技巧和改進 <a class="header-anchor" href="#linux-用户的-7-個-sudo-技巧和改進" aria-label="Permalink to “Linux 用户的 7 個 Sudo 技巧和改進”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202312/14/232352wzxtu2pp6dxg4ou4.jpg" alt=""></p><blockquote><p>用這些技巧釋放 sudo 的力量 💪</p></blockquote><p>你應該熟悉 sudo 吧？肯定有過使用的經驗。</p><p>對多數 Linux 用户來説，<code>sudo</code> 就像一個神器，賦予了他們作為 root 用户執行任意命令或切換到 root 用户身份的能力。</p><p>其實這隻掌握了一半的真相。<code>sudo</code> 絕非僅僅只是一條命令，<strong><code>sudo</code> 是一款你可以根據需求和偏好去定製的工具</strong>。</p><p>Ubuntu、Debian 以及其他的發行版在默認的配置下，賦予了 <code>sudo</code> 以 root 用户的身份執行任意命令的權限。這讓很多用户誤以為 <code>sudo</code> 就像一個魔法開關，瞬間可以獲取到 root 權限。</p><p><strong>比如説，系統管理員可以設置成只有屬於特定的 <code>dev</code> 組的部分用户才能用 <code>sudo</code> 來執行 <code>nginx</code> 命令。這些用户將無法用 <code>sudo</code> 執行任何其他命令或切換到 root 用户。</strong></p><p>如果你對此感到驚訝，那很可能是你一直在使用 <code>sudo</code>，但對其底層的工作原理並沒有太多瞭解。</p><p>在這個教程中，我並不會解釋 <code>sudo</code> 是如何運作的，這個主題我會在另一天講解。</p><p>在這篇文章中，你將看到 <code>sudo</code> 的不同特性可以如何被調試和改進。有些可能真的很有用，有些可能完全沒什麼幫助，但是挺有趣。</p>',11)),e("blockquote",null,[e("p",null,[s[1]||(s[1]=o("🚧 請不要隨意去嘗試所有提到的改進。如果處理不慎，你可能會遭遇無法運行 ",-1)),s[2]||(s[2]=e("code",null,"sudo",-1)),s[3]||(s[3]=o(" 的混亂狀態。在大多數情況下，平靜閲讀並知道這些就好。如果你決定嘗試一些改進步驟，",-1)),i(d,{href:"https://itsfoss.com/backup-restore-linux-timeshift/"},{default:t(()=>[...s[0]||(s[0]=[o("請先備份你的系統設置",-1)])]),_:1}),s[4]||(s[4]=o("，這樣在需要的時候能把事情恢復到正常。",-1))])]),s[45]||(s[45]=e("h3",{id:"_1、編輯-sudo-配置時-請始終使用-visudo",tabindex:"-1"},[o("1、編輯 sudo 配置時，請始終使用 visudo "),e("a",{class:"header-anchor",href:"#_1、編輯-sudo-配置時-請始終使用-visudo","aria-label":"Permalink to “1、編輯 sudo 配置時，請始終使用 visudo”"},"​")],-1)),s[46]||(s[46]=e("p",null,[e("code",null,"sudo"),o(" 命令是通過 "),e("code",null,"/etc/sudoers"),o(" 文件進行配置的。")],-1)),e("p",null,[s[6]||(s[6]=o("雖然你可以用你最喜歡的 ",-1)),i(d,{href:"https://itsfoss.com/command-line-text-editors-linux/"},{default:t(()=>[...s[5]||(s[5]=[o("終端文本編輯器",-1)])]),_:1}),s[7]||(s[7]=o(" 編輯這個文件，比如 Micro、NeoVim 等，但你",-1)),s[8]||(s[8]=e("strong",null,"千萬不要",-1)),s[9]||(s[9]=o("這麼做。",-1))]),s[47]||(s[47]=a('<p>為什麼這麼説呢？因為該文件中的任何語法錯誤都會讓你的系統出問題，導致 <code>sudo</code> 無法工作。這可能會使得你的 Linux 系統無法正常使用。</p><p>你只需要這樣使用即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>傳統上，<code>visudo</code> 命令會在 Vi 編輯器中打開 <code>/etc/sudoers</code> 文件。如果你用的是 Ubuntu，那麼會在 Nano 中打開。</p><p><img src="https://itsfoss.com/content/images/2023/02/save-file-in-nano-editor.png" alt=""></p><p>這麼做的好處在於，<strong>visudo 會在你試圖保存更改時執行語法檢查</strong>。這能確保你不會因為語法錯誤而誤改 <code>sudo</code> 配置。</p><p><img src="https://itsfoss.com/content/images/2023/12/visudo-syntax-validation.png" alt="visudo 在保存到 sudoers 文件的變更前檢查語法"></p><p>好了！現在你可以看看 <code>sudo</code> 配置的一些改變。</p><blockquote><p>💡 我建議你備份 <code>/etc/sudoers</code> 文件（<code>sudo cp /etc/sudoers /etc/sudoers.bak</code>）。這樣，如果你不確定你做了哪些更改，或者你想恢復到默認的 sudo 配置，那你可以從備份文件中複製。</p></blockquote><h3 id="_2、輸入-sudo-密碼時顯示星號" tabindex="-1">2、輸入 sudo 密碼時顯示星號 <a class="header-anchor" href="#_2、輸入-sudo-密碼時顯示星號" aria-label="Permalink to “2、輸入 sudo 密碼時顯示星號”">​</a></h3><p>我們的這種輸入行為是從 UNIX 系統中繼承下來的。當你在終端輸入 <code>sudo</code> 密碼時，屏幕上不會有任何顯示。這種缺乏反饋的現象，往往讓新的 Linux 用户懷疑自己的系統已經卡住了。</p><p>人們常説，這是一項安全功能。或許在上個世紀是這樣，但我個人覺得我們沒有必要繼續這樣下去。</p><p>不過，一些發行版，如 Linux Mint，已經對 <code>sudo</code> 進行了優化，當你輸入密碼時會顯示星號。</p><p>這樣的方式更符合我們的日常經驗。</p><p>如果想讓 <code>sudo</code> 輸入密碼時顯示星號，運行 <code>sudo visudo</code> 並找到以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset</span></span></code></pre></div><p>然後將其更改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset,pwfeedback</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/12/sudo-password-feedback.png" alt=""></p><blockquote><p>💡 在某些發行版中，比如 Arch，你可能找不到 <code>Defaults env_reset</code> 這一行。如果這樣的話，只需新增一行 <code>Defaults env_reset, pwfeedback</code> 就可以了。</p></blockquote><p>現在，當 <code>sudo</code> 需要你輸入密碼時，你會看到輸入的密碼變成了星號。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-password-with-asterisk-display.png" alt=""></p><blockquote><p>✋ 如果你注意到即使密碼正確也無法通過一些圖形化應用，如軟件中心，那就該撤銷這項更改。一些較舊的論壇帖子曾提到過此類問題，雖然我自己還未遇到過。</p></blockquote><h3 id="_3、增加-sudo-密碼超時時限" tabindex="-1">3、增加 sudo 密碼超時時限 <a class="header-anchor" href="#_3、增加-sudo-密碼超時時限" aria-label="Permalink to “3、增加 sudo 密碼超時時限”">​</a></h3><p>當你首次使用 <code>sudo</code> 時，它會要求輸入密碼。但在隨後相當一段時間裏，你使用 <code>sudo</code> 執行命令就無需再次輸入密碼。</p><p>我們將這個時間間隔稱為 <code>sudo</code> 密碼超時 （暫且稱為 SPT，這是我剛剛編的説法，請不要真的這樣稱呼 😁）。</p><p>不同的發行版有不同的超時時間。可能是 5 分鐘，也可能是 15 分鐘。</p><p>你可以根據自己的喜好來改變這個設置，設定一個新的 <code>sudo</code> 密碼超時時限。</p><p>像你之前看到的，編輯 <code>sudoers</code> 文件，找到含有 <code>Defaults env_reset</code> 的行，並在此行添加 <code>timestamp_timeout=XX</code>，使其變成如下形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults        env_reset, timestamp_timeout=XX</span></span></code></pre></div><p>其中 <code>XX</code> 是以分鐘為單位的超時時長。</p><p>如果你還有其他參數，例如你在上一節中看到的星號反饋，它們都可以在一行中組合起來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults        env_reset, timestamp_timeout=XX, pwfeedback</span></span></code></pre></div><blockquote><p>💡 同樣地，你還可以控制密碼重試的次數上限。使用 <code>passwd_tries=N</code> 來修改用户可以輸入錯誤密碼的次數。</p></blockquote><h3 id="_4、在不輸入密碼的情況下使用-sudo" tabindex="-1">4、在不輸入密碼的情況下使用 sudo <a class="header-anchor" href="#_4、在不輸入密碼的情況下使用-sudo" aria-label="Permalink to “4、在不輸入密碼的情況下使用 sudo”">​</a></h3><p>行！你已經增加了 <code>sudo</code> 密碼超時時限（或者稱之為 SPT。哇塞！你還在堅持這個叫法 😛）。</p><p>這樣很好。我的意思是，畢竟沒人願意每幾分鐘就輸入一次密碼。</p><p>擴大超時時限是一方面，另一方面則是儘可能不去使用它。</p><p>是的，你沒聽錯。你就是可以在無需輸入密碼的情況下使用 <code>sudo</code>。</p><p>從安全角度來看，這聽起來似乎很冒險，對吧？的確如此，但在某些實際情況下，你確實會更青睞無密碼的 <code>sudo</code>。</p><p>例如，如果你需要遠程管理多台 Linux 服務器，併為了避免總是使用 root，你在這些服務器上創建了一些 <code>sudo</code> 用户。辛酸的是，你會有太多的密碼。而你又不想對所有的服務器使用同一的 <code>sudo</code> 密碼。</p><p>在這種情況下，你可以僅設置基於密鑰的 SSH 訪問方式，並允許使用無需密碼的 <code>sudo</code>。這樣，只有獲得授權的用户才能訪問遠程服務器，也不用再記住 <code>sudo</code> 密碼。</p>',42)),e("p",null,[s[11]||(s[11]=o("我在 ",-1)),i(d,{href:"https://digitalocean.pxf.io/JzK74r"},{default:t(()=>[...s[10]||(s[10]=[o("DigitalOcean",-1)])]),_:1}),s[12]||(s[12]=o(" 上部署的測試服務器上就採用了這種方法，用來測試開源工具和服務。",-1))]),s[48]||(s[48]=a('<p>好處是這可以按用户進行設置。使用以下命令打開 <code>/etc/sudoers</code> 文件進行編輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>然後添加如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user_name ALL=(ALL) NOPASSWD:ALL</span></span></code></pre></div><p>當然，你需要將上面行中的 <code>user_name</code> 替換為實際的用户名。</p><p>保存文件後，你就可以享受無密碼的 <code>sudo</code> 生活了。</p><h3 id="_5、配置獨立的-sudo-日誌文件" tabindex="-1">5、配置獨立的 sudo 日誌文件 <a class="header-anchor" href="#_5、配置獨立的-sudo-日誌文件" aria-label="Permalink to “5、配置獨立的 sudo 日誌文件”">​</a></h3><p>查閲 syslog 或 journal 日誌，我們可以找到關於 <code>sudo</code> 的所有條目，但若需要單獨針對 <code>sudo</code> 的記錄，可以專門創建一個自定義的日誌文件。例如，選擇 <code>/var/sudo.log</code> 文件來存儲日誌。這個新的日誌文件無需手動創建，如果不存在，系統會自動生成。</p><p>編輯 <code>/etc/sudoers</code> 文件，採用 <code>visudo</code> 命令，並在其中添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults  logfile=&quot;/var/log/sudo.log&quot;</span></span></code></pre></div><p>保存該文件後，便可以在其中查看哪些命令在何時、由哪位用户通過 <code>sudo</code> 運行了。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-log-file.png" alt=""></p><h3 id="_6、限制特定用户組使用-sudo-執行特定命令" tabindex="-1">6、限制特定用户組使用 sudo 執行特定命令 <a class="header-anchor" href="#_6、限制特定用户組使用-sudo-執行特定命令" aria-label="Permalink to “6、限制特定用户組使用 sudo 執行特定命令”">​</a></h3><p>這是一種高級解決方案，系統管理員在需要跨部門共享服務器的多用户環境中會使用。</p>',14)),e("p",null,[s[14]||(s[14]=o("開發者可能會需要以 root 權限運行 Web 服務器或其他程序，但全權給予他們 ",-1)),s[15]||(s[15]=e("code",null,"sudo",-1)),s[16]||(s[16]=o(" 權限會帶來安全風險。我建議在羣組級別進行此項操作。例如，創建命名為 ",-1)),s[17]||(s[17]=e("code",null,"coders",-1)),s[18]||(s[18]=o(" 的羣組，並允許它們運行在 ",-1)),s[19]||(s[19]=e("code",null,"/var/www",-1)),s[20]||(s[20]=o(" 和 ",-1)),s[21]||(s[21]=e("code",null,"/opt/bin/coders",-1)),s[22]||(s[22]=o(" 目錄下的命令（或可執行文件），以及 ",-1)),i(d,{href:"https://itsfoss.com/inxi-system-info-linux/"},{default:t(()=>[...s[13]||(s[13]=[o("inxi 命令",-1)])]),_:1}),s[23]||(s[23]=o("（路徑是 ",-1)),s[24]||(s[24]=e("code",null,"/usr/bin/inxi",-1)),s[25]||(s[25]=o(" 的二進制文件）。這是一個假想情景，實際操作請謹慎對待。",-1))]),s[49]||(s[49]=a('<p>接下來，用 <code>sudo visudo</code> 編輯 sudoer 文件，再添加以下行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%coders   ALL=(ALL:ALL) /var/www,/opt/bin/coders,/usr/bin/inxi</span></span></code></pre></div><p>如有需要，可以添加 <code>NOPASSWD</code> 參數，這樣允許使用 <code>sudo</code> 運行的命令就不再需要密碼了。</p><p>關於 <code>ALL=(ALL:ALL)</code> 的詳細解讀，我們將會在其他文章中進行講解，畢竟這篇文章已經解釋的內容足夠多了。</p><h3 id="_7、檢查用户的-sudo-權限" tabindex="-1">7、檢查用户的 sudo 權限 <a class="header-anchor" href="#_7、檢查用户的-sudo-權限" aria-label="Permalink to “7、檢查用户的 sudo 權限”">​</a></h3><p>好吧，這是個小提示，而不是系統調優技巧。</p><p>如何確認一個用户是否具有 <code>sudo</code> 權限呢？可能有人會説，查看他們是否是 <code>sudo</code> 組的成員。但這並不一定準確，因為有些發行版用的是 <code>wheel</code> 代替 <code>sudo</code> 分組。</p><p>更佳的方法是利用 <code>sudo</code> 內建的功能，看看用户具有哪種 <code>sudo</code> 權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo -l -U user_name</span></span></code></pre></div><p>這將顯示出用户具有執行部分命令或所有命令的 <code>sudo</code> 權限。</p><p><img src="https://itsfoss.com/content/images/2023/12/check-sudo-access.png" alt=""></p><p>如你所見，我擁有自定義日誌文件、密碼反饋以及執行所有命令的 <code>sudo</code> 權限。</p><p>如果一個用户完全沒有 <code>sudo</code> 權限，你將看到如下提示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>User prakash is not allowed to run sudo on this-that-server.</span></span></code></pre></div><h3 id="🎁-附加內容-輸錯-sudo-密碼時-讓系統-侮辱-你" tabindex="-1">🎁 附加內容：輸錯 sudo 密碼時，讓系統“侮辱”你 <a class="header-anchor" href="#🎁-附加內容-輸錯-sudo-密碼時-讓系統-侮辱-你" aria-label="Permalink to “🎁 附加內容：輸錯 sudo 密碼時，讓系統“侮辱”你”">​</a></h3><p>這是個我在文章開頭提到的“無用”小調整。</p><p>我想你在使用 <code>sudo</code> 時肯定曾誤輸過密碼，對吧？</p>',17)),e("p",null,[s[27]||(s[27]=o("這個小技巧就是，在你每次輸錯密碼時，",-1)),i(d,{href:"https://itsfoss.com/sudo-insult-linux/"},{default:t(()=>[...s[26]||(s[26]=[o("讓 sudo 拋出隨機的“侮辱”",-1)])]),_:1}),s[28]||(s[28]=o("。",-1))]),s[50]||(s[50]=a('<p>用 <code>sudo visudo</code> 修改 <code>sudo</code> 配置文件，然後添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults   insults</span></span></code></pre></div><p>修改後，你可以故意輸錯密碼，測試新的設置。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-insults.png" alt=""></p><p>你可能在想，誰會喜歡被侮辱呢？<strong>只有粉絲</strong>可以以直白的方式告訴你 😇</p><h3 id="你是如何運用-sudo-的" tabindex="-1">你是如何運用 sudo 的？ <a class="header-anchor" href="#你是如何運用-sudo-的" aria-label="Permalink to “你是如何運用 sudo 的？”">​</a></h3><p><img src="https://itsfoss.com/content/images/2023/12/sudo-meme.png" alt=""></p><p>我知道定製化的可能性無窮無盡，但其實，一般的 Linux 用户並不會去自定義 <code>sudo</code>。</p><p>儘管如此，我還是熱衷於與你分享這些因為你可能會發現一些新奇且實用的東西。</p><p>💬 那麼，你有發現什麼新的東西嗎？請在評論區告訴我。你有一些秘密的 <code>sudo</code> 技巧歡迎和大家分享！</p><p><em>（題圖：DA/a12900e5-e197-455e-adfc-0b52e4305b91）</em></p><hr>',12)),e("p",null,[s[30]||(s[30]=o("via: ",-1)),i(d,{href:"https://itsfoss.com/sudo-tips/"},{default:t(()=>[...s[29]||(s[29]=[o("https://itsfoss.com/sudo-tips/",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=o("作者：",-1)),i(d,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[31]||(s[31]=[o("Abhishek Prakash",-1)])]),_:1}),s[36]||(s[36]=o(" 選題：",-1)),i(d,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[32]||(s[32]=[o("lujun9972",-1)])]),_:1}),s[37]||(s[37]=o(" 譯者：",-1)),i(d,{href:"https://linux.cn/lctt/ChatGPT"},{default:t(()=>[...s[33]||(s[33]=[o("ChatGPT",-1)])]),_:1}),s[38]||(s[38]=o(" 校對：",-1)),i(d,{href:"https://github.com/wxy"},{default:t(()=>[...s[34]||(s[34]=[o("wxy",-1)])]),_:1})]),e("p",null,[s[41]||(s[41]=o("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[39]||(s[39]=[o("LCTT",-1)])]),_:1}),s[42]||(s[42]=o(" 原創編譯，",-1)),i(d,{href:"https://linux.cn/"},{default:t(()=>[...s[40]||(s[40]=[o("Linux中國",-1)])]),_:1}),s[43]||(s[43]=o(" 榮譽推出",-1))])])}const v=p(r,[["render",g]]);export{T as __pageData,v as default};
